def build_bot(data: dict) -> str:
    key = data["template"]
    if key not in TEMPLATES:
        raise ValueError("قالب نامعتبر است.")
    kind = TEMPLATE_META[key]["kind"]
    parsed = parse_detail(kind, data.get("detail", ""))
    cfg = {**data, **parsed}
    brand = cfg.get("brand_name") or cfg.get("brand") or "MyBot"
    welcome = cfg.get("welcome_text") or cfg.get("welcome") or f"به {brand} خوش آمدید"
    cfg["brand_name"] = brand
    cfg["welcome_text"] = welcome
    cfg["profile"] = {
        "key": key,
        "label": TEMPLATES[key],
        "category": TEMPLATE_META[key]["category"],
        "engine": TEMPLATE_META[key]["engine"],
        "features": TEMPLATE_META[key]["features"],
    }
    cfg["channel"] = cfg.get("channel", "@yourchannel")
    return _render_generated(cfg, TEMPLATES[key])


def _render_generated(cfg: dict, label: str) -> str:
    code = _GENERATOR_TEMPLATE
    brand = cfg.get("brand_name") or cfg.get("brand") or "MyBot"
    welcome = cfg.get("welcome_text") or cfg.get("welcome") or "خوش آمدید"
    for placeholder, value in {
        "__CHANNEL__": _q(cfg.get("channel", "@yourchannel")),
        "__BRAND__": _q(brand),
        "__WELCOME__": _q(welcome),
        "__TEMPLATE__": _q(label),
        "__CONFIG__": _q(cfg),
    }.items():
        code = code.replace(placeholder, value)
    return code



def build_bot(data: dict) -> str:
    key = data["template"]
    if key not in TEMPLATES:
        raise ValueError("قالب نامعتبر است.")
    kind = TEMPLATE_META[key]["kind"]
    parsed = parse_detail(kind, data.get("detail", ""))
    cfg = {**data, **parsed}
    brand = cfg.get("brand_name") or cfg.get("brand") or "MyBot"
    welcome = cfg.get("welcome_text") or cfg.get("welcome") or f"به {brand} خوش آمدید"
    cfg["brand_name"] = brand
    cfg["welcome_text"] = welcome
    cfg["profile"] = {
        "key": key,
        "label": TEMPLATES[key],
        "category": TEMPLATE_META[key]["category"],
        "engine": TEMPLATE_META[key]["engine"],
        "features": TEMPLATE_META[key]["features"],
    }
    cfg["channel"] = cfg.get("channel", "@yourchannel")
    return _render_generated(cfg, TEMPLATES[key])


def _render_generated(cfg: dict, label: str) -> str:
    code = _GENERATOR_TEMPLATE
    brand = cfg.get("brand_name") or cfg.get("brand") or "MyBot"
    welcome = cfg.get("welcome_text") or cfg.get("welcome") or "خوش آمدید"
    for placeholder, value in {
        "__CHANNEL__": _q(cfg.get("channel", "@yourchannel")),
        "__BRAND__": _q(brand),
        "__WELCOME__": _q(welcome),
        "__TEMPLATE__": _q(label),
        "__CONFIG__": _q(cfg),
    }.items():
        code = code.replace(placeholder, value)
    return code


