def build_package(data: dict) -> bytes:
    import io
    import zipfile
    code = build_bot(data)
    key = data["template"]
    label = TEMPLATES[key]
    requirements = "aiogram==3.13.1\npython-dotenv==1.0.1\npsycopg[binary]==3.2.3\n"
    admin = data.get("admin_id") or ""
    env_example = f"BOT_TOKEN=\nADMIN_ID={admin}\nDATABASE_URL=\n# CHANNEL=@yourchannel\n# PAYMENT_URL=https://example.com/pay\n"
    readme = f"# {label} — Railway Ready\n\nVariables: BOT_TOKEN, ADMIN_ID, DATABASE_URL\nStart: python bot.py\n"
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("bot.py", code)
        z.writestr("requirements.txt", requirements)
        z.writestr(".env.example", env_example)
        z.writestr("README.md", readme)
    return buf.getvalue()
